from collections import Counter

text = """The quick brown fox jumps over the lazy dog.
The dog sleeps; the fox runs. The end."""

words = text.lower().replace(".", "").replace(";", "").split()

counts = {}
for word in words:
    counts[word] = counts.get(word, 0) + 1

for word, count in sorted(counts.items(), key=lambda pair: pair[1], reverse=True)[:3]:
    print(f"{word:<6}{count}")

print(Counter(words).most_common(3))

def is_palindrome(text: str) -> bool:
    cleaned = "".join(ch.lower() for ch in text if ch.isalnum())
    return cleaned == cleaned[::-1]


for phrase in ["racecar", "A man, a plan, a canal: Panama", "Python"]:
    print(f"{phrase!r}: {is_palindrome(phrase)}")

import random

secret = random.randint(1, 20)
attempts = 0

while True:
    try:
        guess = int(input("Guess a number from 1 to 20: "))
    except ValueError:
        print("Please type a whole number.")
        continue
    attempts += 1
    if guess < secret:
        print("Too low.")
    elif guess > secret:
        print("Too high.")
    else:
        print(f"Correct! You needed {attempts} attempts.")
        break

class TodoList:
    def __init__(self):
        self.tasks = []

    def add(self, title):
        self.tasks.append({"title": title, "done": False})

    def complete(self, title):
        for task in self.tasks:
            if task["title"] == title:
                task["done"] = True
                return True
        return False

    def __len__(self):
        return len(self.tasks)

    def __str__(self):
        lines = [f"[{'x' if t['done'] else ' '}] {t['title']}" for t in self.tasks]
        return "\n".join(lines)


todo = TodoList()
todo.add("Write lesson")
todo.add("Review quiz")
todo.add("Publish")
todo.complete("Write lesson")
print(todo)
print(len(todo), "tasks,", sum(t["done"] for t in todo.tasks), "done")

import json
from pathlib import Path

DEFAULTS = {"theme": "light", "font_size": 12, "autosave": True}
path = Path("settings.json")

if path.exists():
    saved = json.loads(path.read_text(encoding="utf-8"))
else:
    saved = {}

settings = DEFAULTS | saved | {"font_size": 14}
path.write_text(json.dumps(settings, indent=2), encoding="utf-8")

print(settings)
print(path.read_text(encoding="utf-8"))

from dataclasses import dataclass


@dataclass
class Player:
    name: str
    wins: int
    losses: int

    @property
    def win_rate(self) -> float:
        games = self.wins + self.losses
        return self.wins / games if games else 0.0


players = [Player("Mina", 12, 3), Player("Ravi", 7, 7), Player("Sofia", 15, 1)]

for rank, player in enumerate(sorted(players, key=lambda p: p.win_rate, reverse=True), start=1):
    print(f"{rank}. {player.name:<6}{player.win_rate:.0%}")

print(players[0])
